"""V2-1 (spec §3.10): `start` refuses a stale training_handler.py, not only a stale lock. Deps-free.

* cloud_training_api/app/services/training_handler_hash.py is GENERATED by
  modal_training/make_handler_hash.py from training_handler.py's bytes; this file fails
  until the generator was re-run after an edit to the handler.
* The worker hashes, at run time, the very file it runs (HANDLER_PATH = its own
  __file__) and that is the repo file's bytes in every image that runs it: the trainer
  image and the CPU proof image COPY it verbatim, Modal mounts it with
  add_local_python_source; .gitattributes keeps it LF so a Windows checkout hashes alike.
* The generator's --check refuses a stale hash file and its generate() repairs it.
"""

from __future__ import annotations

import ast
import hashlib
import re
import subprocess
import sys
import tempfile
import types
import unittest
from pathlib import Path
from unittest import mock

_SETUP = Path(__file__).resolve().parents[1]
_REPO = _SETUP.parent
_MODAL = _SETUP / "modal_training"
if str(_MODAL) not in sys.path:
    sys.path.insert(0, str(_MODAL))

import make_handler_hash as mhh  # noqa: E402

HANDLER = _MODAL / "training_handler.py"
HASH_FILE = _SETUP / "cloud_training_api" / "app" / "services" / "training_handler_hash.py"
TRAINER_DOCKERFILE = _SETUP / "runpod_training" / "Dockerfile"
PROOF_DOCKERFILE = _SETUP / "runpod_training" / "proof" / "Dockerfile.proof"
MODAL_APP = _MODAL / "modal_app.py"


def _constant(path: Path, name: str):
    for node in ast.parse(path.read_text(encoding="utf-8")).body:
        if isinstance(node, ast.Assign) and any(isinstance(t, ast.Name) and t.id == name for t in node.targets):
            return ast.literal_eval(node.value)
    raise AssertionError(f"{path.name} has no module constant {name}")


def _import_handler():
    """training_handler with the CI stubs of huggingface_hub and supabase (house pattern)."""
    for name in ("huggingface_hub", "huggingface_hub.utils", "supabase"):
        sys.modules.setdefault(name, types.ModuleType(name))
    hub = sys.modules["huggingface_hub"]
    for attr in ("HfApi", "hf_hub_download", "login"):
        if not hasattr(hub, attr):
            setattr(hub, attr, lambda *a, **k: None)
    utils = sys.modules["huggingface_hub.utils"]
    for attr in ("HfHubHTTPError", "RepositoryNotFoundError", "RevisionNotFoundError"):
        if not hasattr(utils, attr):
            setattr(utils, attr, type(attr, (Exception,), {}))
    if not hasattr(sys.modules["supabase"], "create_client"):
        sys.modules["supabase"].create_client = lambda *a, **k: None
    import training_handler
    return training_handler


class TheGeneratedHash(unittest.TestCase):
    def test_the_hash_file_is_the_handlers_sha256(self):
        digest = hashlib.sha256(HANDLER.read_bytes()).hexdigest()
        self.assertEqual(_constant(HASH_FILE, "TRAINING_HANDLER_SHA256"), digest,
                         "training_handler.py changed: run modal_training/make_handler_hash.py")
        self.assertEqual(HASH_FILE.read_text(encoding="utf-8"), mhh.render_hash_module(HANDLER.read_bytes()),
                         "regenerate with make_handler_hash.py; never edit the hash file by hand")

    def test_check_mode_agrees(self):
        self.assertEqual(mhh.check(), 0)
        self.assertEqual(mhh.main(["--check"]), 0)
        self.assertEqual(mhh.main(["--bogus"]), 2)

    def test_check_refuses_a_stale_file_and_generate_repairs_it(self):
        with tempfile.TemporaryDirectory() as d:
            handler, out = Path(d) / "training_handler.py", Path(d) / "training_handler_hash.py"
            handler.write_bytes(HANDLER.read_bytes())
            self.assertEqual(mhh.generate(handler, out), 0)
            self.assertEqual(mhh.check(handler, out), 0)
            handler.write_bytes(HANDLER.read_bytes() + b"# one more line\n")
            self.assertEqual(mhh.check(handler, out), 1)
            self.assertEqual(mhh.generate(handler, out), 0)
            self.assertEqual(_constant(out, "TRAINING_HANDLER_SHA256"),
                             hashlib.sha256(handler.read_bytes()).hexdigest())
            out.unlink()
            self.assertEqual(mhh.check(handler, out), 1)

    def test_the_command_line_check_runs_without_dependencies(self):
        r = subprocess.run([sys.executable, "-I", str(_MODAL / "make_handler_hash.py"), "--check"],
                           capture_output=True, text=True)
        self.assertEqual(r.returncode, 0, r.stderr)
        self.assertIn("OK: TRAINING_HANDLER_SHA256 = ", r.stdout)

    def test_the_paths_are_the_repo_files(self):
        self.assertEqual(mhh.HANDLER_PATH, HANDLER.resolve())
        self.assertEqual(mhh.HASH_PATH, HASH_FILE.resolve())


class TheWorkerHashesWhatItRuns(unittest.TestCase):
    def test_the_worker_hashes_its_own_file_and_matches_the_generated_constant(self):
        th = _import_handler()
        self.assertEqual(Path(th.HANDLER_PATH).resolve(), Path(th.__file__).resolve())
        self.assertEqual(Path(th.__file__).resolve(), HANDLER.resolve())
        self.assertEqual(th._handler_sha256(), _constant(HASH_FILE, "TRAINING_HANDLER_SHA256"))

    def test_an_unreadable_handler_sends_zeros(self):
        th = _import_handler()
        with tempfile.TemporaryDirectory() as d, \
                mock.patch.object(th, "HANDLER_PATH", Path(d) / "absent.py"):
            self.assertEqual(th._handler_sha256(), "0" * 64)

    def test_the_handler_file_is_lf_only_and_pinned_so(self):
        self.assertNotIn(b"\r", HANDLER.read_bytes())
        attrs = (_REPO / ".gitattributes").read_text(encoding="utf-8").splitlines()
        self.assertIn("robotis_ai_setup/modal_training/training_handler.py text eol=lf",
                      [re.sub(r"\s+", " ", ln).strip() for ln in attrs])


class WorkerAndApiAgree(unittest.TestCase):
    def test_the_worker_sends_the_key_the_api_compares_from_the_generated_module(self):
        route = (_SETUP / "cloud_training_api" / "app" / "routes" / "training_worker.py").read_text(encoding="utf-8")
        self.assertIn('body.get("handler_sha256")', route)
        self.assertIn(f"from app.services import {mhh.HASH_PATH.stem}", route)
        self.assertIn("training_handler_hash.TRAINING_HANDLER_SHA256", route)
        self.assertIn('"handler_sha256": _handler_sha256()', HANDLER.read_text(encoding="utf-8"))


class EveryImageShipsTheHashedFileVerbatim(unittest.TestCase):
    def test_the_trainer_and_proof_images_copy_it_and_nothing_rewrites_it(self):
        for dockerfile in (TRAINER_DOCKERFILE, PROOF_DOCKERFILE):
            with self.subTest(dockerfile=dockerfile.name):
                text = dockerfile.read_text(encoding="utf-8")
                copies = [ln for ln in text.splitlines() if "training_handler.py" in ln]
                self.assertEqual(copies,
                                 ["COPY robotis_ai_setup/modal_training/training_handler.py /app/training_handler.py"])
                self.assertIn("PYTHONPATH=/app", text, "the worker imports /app/training_handler.py")

    def test_the_modal_image_mounts_the_module_itself(self):
        code = "\n".join(ln for ln in MODAL_APP.read_text(encoding="utf-8").splitlines()
                         if not ln.strip().startswith("#"))
        self.assertIn('.add_local_python_source("training_handler")', code)
        self.assertNotRegex(code, r"add_local_(file|dir)\([^)]*training_handler",
                            "no second copy of the handler in the Modal image")
        self.assertIn("from training_handler import run_managed", code)


if __name__ == "__main__":
    unittest.main()
